var a=`0230-moussaka`;var n=`world-0230`;var o=`GR`;var i=`southern-europe`;var r=4;var s=95;var l={en:`Moussaka`,ua:`Мусака`};var g={en:`A traditional Greece dish made with eggplant, potato, ground lamb, yellow onion. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: баклажан, картопля, фарш з ягнятини, жовта цибуля. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Cut the vegetables evenly and roast at 200°C for about 22 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 22 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:22,i:[[`eggplant`,600,`g`],[`potato`,350,`g`],[`extra-virgin-olive-oil`,75,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 16 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 16 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:16,i:[[`ground-lamb`,550,`g`],[`yellow-onion`,160,`g`],[`tomato-passata`,350,`g`],[`ground-cinnamon`,3,`g`],[`extra-virgin-olive-oil`,25,`ml`]]},{en:`Melt the fat, stir in flour and cook gently for about 10 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 10 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:10,i:[[`unsalted-butter`,65,`g`],[`all-purpose-flour`,70,`g`],[`whole-cow-milk`,620,`ml`],[`ground-nutmeg`,2,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Arrange roasted potatoes and eggplant in layers with the browned lamb tomato ragù, and cover evenly with béchamel.`,ua:`Викладіть шарами підпечену картоплю, баклажани й м’ясне рагу з помідорами, рівномірно покрийте бешамелем.`,t:[`layered-assembly`],m:7,i:[]},{en:`Bake the layered moussaka at 180°C for about 40 minutes until bubbling and golden, then rest 15 minutes before slicing.`,ua:`Запікайте мусаку при 180°C близько 40 хвилин до кипіння та золотавої скоринки, дайте постояти 15 хвилин перед нарізанням.`,t:[`baking`],m:40,i:[[`parmigiano-reggiano`,75,`g`]]}];var d={slug:a,id:n,country:`GR`,region:i,servings:4,minutes:95,title:l,text:g,steps:u};export{o as country,d as default,n as id,s as minutes,i as region,r as servings,a as slug,u as steps,g as text,l as title};